  ('64476eda-c361-5971-8e7d-81b0b26e7d31', null, (select id from public.skills where slug = 'read-g10-evidence-inference'), null, 'medium',
   $q$Which detail best supports the claim that route 14 became more reliable?$q$, $q$[{"text":"Buses arriving within two minutes of schedule rose from fifty-eight to eighty-one percent.","is_correct":true},{"text":"Ridership on route 14 climbed by twelve percent in one year.","is_correct":false,"misconception_token":"supports-different-claim"},{"text":"Each bus carries a small radio transmitter that talks to signals.","is_correct":false,"misconception_token":"describes-method"},{"text":"The route crossed downtown through twenty-two traffic signals.","is_correct":false,"misconception_token":"irrelevant-detail"}]$q$::jsonb, $q$Buses arriving within two minutes of schedule rose from fifty-eight to eighty-one percent.$q$, $q$Reliability means buses arriving when the schedule says, and the share of on-time buses rose sharply. Ridership growth is popularity, and the passage notes it may also reflect the new student discount.$q$, 'draft', '2a608e7a-88c7-5ab8-b406-52d9b9a1ba2e')
